<div class="topline"><span>TURN EXPERIENCE INTO PROGRESS</span><span>Notice. Learn. Act.</span></div><header class="page-header"><div><h1>Make the lesson count.</h1><p class="muted">A setback becomes useful when it changes your next step.</p></div><a class="btn" href="/review">Weekly review →</a></header>
<?php require ROOT.'/app/Core/views/notices.php'; ?>
<?php foreach ($repeated as $pattern): ?><div class="notice warning"><strong>Recurring pattern · <?= e($pattern['area']) ?></strong><br><?= e($pattern['n']) ?> failures logged in 90 days. Review the root causes and try a different action.</div><?php endforeach; ?>
<div class="two-col"><section class="card"><h2>Log a failure. Find a way forward.</h2><form class="stack" method="post" action="/lessons"><?= csrf_field() ?><label>Area<select name="area"><?php foreach (LessonService::AREAS as $area): ?><option><?= e($area) ?></option><?php endforeach; ?></select></label><label>What happened?<textarea name="what_happened" maxlength="3000" rows="3" required></textarea></label><label>Root cause<textarea name="root_cause" maxlength="3000" rows="2" placeholder="What made this happen?"></textarea></label><label>What did you learn?<textarea name="lesson" maxlength="3000" rows="2"></textarea></label><label>Next action<input name="action" maxlength="200" placeholder="A specific step — becomes a task"></label><label>Action due date<input type="date" name="due"></label><button>Save lesson</button></form></section>
<section class="card"><h2>Your next actions</h2><?php require __DIR__.'/tasks.php'; ?><h3>Add a task</h3><form class="stack" method="post" action="/tasks"><?= csrf_field() ?><label>Task<input name="title" maxlength="200" required></label><label>Due date (optional)<input type="date" name="due"></label><button class="secondary">Add task</button></form><?php if ($completed): ?><details class="completed"><summary>Completed tasks (latest 30)</summary><?php foreach ($completed as $t): ?><div class="task-row"><span><?= e($t['title']) ?></span><form method="post" action="/tasks/<?= e($t['id']) ?>/reopen"><?= csrf_field() ?><button class="quiet">Reopen</button></form></div><?php endforeach; ?></details><?php endif; ?></section></div>
<section class="card"><h2>Your lesson journal</h2><p class="muted">Open → applied when the action is done → verified when you confirm the failure has not repeated.</p><?php if (!$lessons): ?><div class="empty"><h3>Your experience belongs here.</h3><p>Log your first lesson above.</p></div><?php else: foreach ($lessons as $l): ?><article class="lesson-entry"><div class="section-heading"><span class="badge"><?= e($l['area']) ?> · <?= e(substr($l['created_at'],0,10)) ?></span><span class="muted"><?= e(ucfirst($l['status'])) ?></span></div><h3><?= e($l['what_happened']) ?></h3><dl class="lesson-detail"><dt>Root cause</dt><dd><?= e($l['root_cause'] ?: 'Not recorded') ?></dd><dt>Lesson</dt><dd><?= e($l['lesson'] ?: 'Not recorded') ?></dd><dt>Action</dt><dd><?= e($l['action'] ?: 'No action added') ?><?= $l['task_status'] ? ' · Task '.e($l['task_status']) : '' ?></dd></dl><div class="section-heading"><form class="inline" method="post" action="/lessons/<?= e($l['id']) ?>/status"><?= csrf_field() ?><select name="status" aria-label="Status for lesson <?= e($l['id']) ?>"><?php foreach (['open','applied','verified'] as $status): ?><option value="<?= e($status) ?>" <?= $l['status']===$status ? 'selected' : '' ?>><?= e(ucfirst($status)) ?></option><?php endforeach; ?></select><button class="secondary">Update</button></form><form method="post" action="/lessons/<?= e($l['id']) ?>/delete" data-confirm="Delete this lesson and its linked action task?"><?= csrf_field() ?><button class="delete">Delete lesson</button></form></div></article><?php endforeach; endif; ?></section>
